using System;
using System.Text;
using Int2Dds.Cdr;
using Xunit;

namespace Int2Dds.Tests
{
    /// <summary>
    /// Cross-language CDR wire-format reference vectors (#385). The hex constants
    /// are generated by the Rust core serializers (the source of truth) and shared
    /// with dds/src/serialize/core/cdr_wire_format_tests.rs and
    /// python/tests/test_cdr_wire_format.py. Round-trip tests cannot catch a
    /// writer/reader pair drifting together; these can.
    /// Regenerate: cargo test -p int2dds --lib cdr_wire_format -- --ignored --nocapture
    /// </summary>
    public class CdrWireFormatTests
    {
        private static readonly string[][] Vectors =
        {
            new[] { "bool_true", "xcdr1_le", "0001000001" },
            new[] { "bool_true", "xcdr1_be", "0000000001" },
            new[] { "bool_true", "xcdr2_le", "0007000001" },
            new[] { "u8", "xcdr1_le", "00010000ab" },
            new[] { "u8", "xcdr1_be", "00000000ab" },
            new[] { "u8", "xcdr2_le", "00070000ab" },
            new[] { "i8", "xcdr1_le", "00010000fb" },
            new[] { "i8", "xcdr1_be", "00000000fb" },
            new[] { "i8", "xcdr2_le", "00070000fb" },
            new[] { "u16", "xcdr1_le", "00010000efbe" },
            new[] { "u16", "xcdr1_be", "00000000beef" },
            new[] { "u16", "xcdr2_le", "00070000efbe" },
            new[] { "i16", "xcdr1_le", "00010000c7cf" },
            new[] { "i16", "xcdr1_be", "00000000cfc7" },
            new[] { "i16", "xcdr2_le", "00070000c7cf" },
            new[] { "u32", "xcdr1_le", "00010000efbeadde" },
            new[] { "u32", "xcdr1_be", "00000000deadbeef" },
            new[] { "u32", "xcdr2_le", "00070000efbeadde" },
            new[] { "i32", "xcdr1_le", "00010000eb32a4f8" },
            new[] { "i32", "xcdr1_be", "00000000f8a432eb" },
            new[] { "i32", "xcdr2_le", "00070000eb32a4f8" },
            new[] { "u64", "xcdr1_le", "000100008877665544332211" },
            new[] { "u64", "xcdr1_be", "000000001122334455667788" },
            new[] { "u64", "xcdr2_le", "000700008877665544332211" },
            new[] { "i64", "xcdr1_le", "00010000eb7e16820befddee" },
            new[] { "i64", "xcdr1_be", "00000000eeddef0b82167eeb" },
            new[] { "i64", "xcdr2_le", "00070000eb7e16820befddee" },
            new[] { "f32", "xcdr1_le", "000100000000c03f" },
            new[] { "f32", "xcdr1_be", "000000003fc00000" },
            new[] { "f32", "xcdr2_le", "000700000000c03f" },
            new[] { "f64", "xcdr1_le", "0001000000000000000006c0" },
            new[] { "f64", "xcdr1_be", "00000000c006000000000000" },
            new[] { "f64", "xcdr2_le", "0007000000000000000006c0" },
            new[] { "string", "xcdr1_le", "000100000600000068656c6c6f00" },
            new[] { "string", "xcdr1_be", "000000000000000668656c6c6f00" },
            new[] { "string", "xcdr2_le", "000700000600000068656c6c6f00" },
            new[] { "string_empty", "xcdr1_le", "000100000100000000" },
            new[] { "string_empty", "xcdr1_be", "000000000000000100" },
            new[] { "string_empty", "xcdr2_le", "000700000100000000" },
            new[] { "wstring", "xcdr1_le", "0001000003000000770003265cd5" },
            new[] { "wstring", "xcdr1_be", "000000000000000300772603d55c" },
            new[] { "wstring", "xcdr2_le", "0007000003000000770003265cd5" },
            new[] { "wstring_empty", "xcdr1_le", "0001000000000000" },
            new[] { "wstring_empty", "xcdr1_be", "0000000000000000" },
            new[] { "wstring_empty", "xcdr2_le", "0007000000000000" },
            new[] { "bytes", "xcdr1_le", "00010000050000000102030405" },
            new[] { "bytes", "xcdr1_be", "00000000000000050102030405" },
            new[] { "bytes", "xcdr2_le", "00070000050000000102030405" },
            new[] { "seq_u32", "xcdr1_le", "000100000300000001000000ffffff7fffffffff" },
            new[] { "seq_u32", "xcdr1_be", "0000000000000003000000017fffffffffffffff" },
            new[] { "seq_u32", "xcdr2_le", "000700000300000001000000ffffff7fffffffff" },
            new[] { "mixed", "xcdr1_le", "0001000042000000000000000807060504030201feff00000d0c0b0a030000006f6b0000000000000000f03f" },
            new[] { "mixed", "xcdr1_be", "0000000042000000000000000102030405060708fffe00000a0b0c0d000000036f6b00003ff0000000000000" },
            new[] { "mixed", "xcdr2_le", "00070000420000000807060504030201feff00000d0c0b0a030000006f6b0000000000000000f03f" },
        };

        private static CdrWriter CreateWriter(string fmt)
        {
            switch (fmt)
            {
                case "xcdr1_le": return new CdrWriter(Extensibility.Final, true, false);
                case "xcdr1_be": return new CdrWriter(Extensibility.Final, false, false);
                case "xcdr2_le": return new CdrWriter(Extensibility.Final, true, true);
                default: throw new ArgumentException(fmt);
            }
        }

        private static void WriteShape(CdrWriter w, string shape)
        {
            switch (shape)
            {
                case "bool_true": w.WriteBool(true); break;
                case "u8": w.WriteU8(0xAB); break;
                case "i8": w.WriteI8(-5); break;
                case "u16": w.WriteU16(0xBEEF); break;
                case "i16": w.WriteI16(-12345); break;
                case "u32": w.WriteU32(0xDEADBEEFu); break;
                case "i32": w.WriteI32(-123456789); break;
                case "u64": w.WriteU64(0x1122334455667788UL); break;
                case "i64": w.WriteI64(-1234567890123456789L); break;
                case "f32": w.WriteF32(1.5f); break;
                case "f64": w.WriteF64(-2.75); break;
                case "string": w.WriteString("hello"); break;
                case "string_empty": w.WriteString(""); break;
                case "wstring": w.WriteWString("w☃한"); break;
                case "wstring_empty": w.WriteWString(""); break;
                case "bytes":
                    w.WriteSeqHeader(5);
                    w.WriteBytes(new byte[] { 1, 2, 3, 4, 5 });
                    break;
                case "seq_u32":
                    w.WriteSeqHeader(3);
                    w.WriteU32(1u);
                    w.WriteU32(0x7FFFFFFFu);
                    w.WriteU32(0xFFFFFFFFu);
                    break;
                case "mixed":
                    w.WriteU8(0x42);
                    w.WriteU64(0x0102030405060708UL);
                    w.WriteI16(-2);
                    w.WriteU32(0x0A0B0C0Du);
                    w.WriteString("ok");
                    w.WriteF64(1.0);
                    break;
                default: throw new ArgumentException(shape);
            }
        }

        private static void ReadShape(CdrReader r, string shape)
        {
            switch (shape)
            {
                case "bool_true": Assert.True(r.ReadBool()); break;
                case "u8": Assert.Equal((byte)0xAB, r.ReadU8()); break;
                case "i8": Assert.Equal((sbyte)-5, r.ReadI8()); break;
                case "u16": Assert.Equal((ushort)0xBEEF, r.ReadU16()); break;
                case "i16": Assert.Equal((short)-12345, r.ReadI16()); break;
                case "u32": Assert.Equal(0xDEADBEEFu, r.ReadU32()); break;
                case "i32": Assert.Equal(-123456789, r.ReadI32()); break;
                case "u64": Assert.Equal(0x1122334455667788UL, r.ReadU64()); break;
                case "i64": Assert.Equal(-1234567890123456789L, r.ReadI64()); break;
                case "f32": Assert.Equal(1.5f, r.ReadF32()); break;
                case "f64": Assert.Equal(-2.75, r.ReadF64()); break;
                case "string": Assert.Equal("hello", r.ReadString()); break;
                case "string_empty": Assert.Equal(string.Empty, r.ReadString()); break;
                case "wstring": Assert.Equal("w☃한", r.ReadWString()); break;
                case "wstring_empty": Assert.Equal(string.Empty, r.ReadWString()); break;
                case "bytes":
                    Assert.Equal(5u, r.ReadSeqHeader());
                    Assert.Equal(new byte[] { 1, 2, 3, 4, 5 }, r.ReadBytes(5));
                    break;
                case "seq_u32":
                    Assert.Equal(3u, r.ReadSeqHeader());
                    Assert.Equal(1u, r.ReadU32());
                    Assert.Equal(0x7FFFFFFFu, r.ReadU32());
                    Assert.Equal(0xFFFFFFFFu, r.ReadU32());
                    break;
                case "mixed":
                    Assert.Equal((byte)0x42, r.ReadU8());
                    Assert.Equal(0x0102030405060708UL, r.ReadU64());
                    Assert.Equal((short)-2, r.ReadI16());
                    Assert.Equal(0x0A0B0C0Du, r.ReadU32());
                    Assert.Equal("ok", r.ReadString());
                    Assert.Equal(1.0, r.ReadF64());
                    break;
                default: throw new ArgumentException(shape);
            }
        }

        private static byte[] FromHex(string hex)
        {
            var bytes = new byte[hex.Length / 2];
            for (int i = 0; i < bytes.Length; i++)
                bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            return bytes;
        }

        private static string ToHex(byte[] bytes)
        {
            var sb = new StringBuilder(bytes.Length * 2);
            foreach (var b in bytes)
                sb.Append(b.ToString("x2"));
            return sb.ToString();
        }

        [Fact]
        public void Writers_ProduceReferenceBytes()
        {
            foreach (var v in Vectors)
            {
                var w = CreateWriter(v[1]);
                WriteShape(w, v[0]);
                Assert.Equal(v[0] + "/" + v[1] + ":" + v[2], v[0] + "/" + v[1] + ":" + ToHex(w.ToBytes()));
            }
        }

        [Fact]
        public void Readers_ConsumeReferenceBytes()
        {
            foreach (var v in Vectors)
            {
                var r = new CdrReader(FromHex(v[2]));
                ReadShape(r, v[0]);
                Assert.True(r.Remaining == 0, v[0] + "/" + v[1] + ": " + r.Remaining + " bytes left unread");
            }
        }
    }
}
